def bundesland(plz):
    """Bundesland zu einer PLZ: erst pgeocode (genau), sonst Präfix-Tabelle (Näherung)."""
    plz = str(plz).strip().zfill(5)
    if not plz.isdigit():
        return ""
    try:
        import pgeocode
        global _NOMI
        if "_NOMI" not in globals():
            _NOMI = pgeocode.Nominatim("de")
        r = _NOMI.query_postal_code(plz)
        if isinstance(r.state_name, str) and r.state_name:
            return r.state_name
    except Exception:
        pass
    return PLZ3.get(plz[:3], "")
